begin;
select no_plan();
select ok(not has_function_privilege('anon','api_v1.list_dashboard_audit_v1(uuid,text,timestamp with time zone,timestamp with time zone,uuid,jsonb)','execute'),'anonymous cannot read audit');
select ok(not has_function_privilege('authenticated','api_v1.get_payment_onboarding_intent_v1(uuid)','execute'),'members cannot read provider intent credentials');
select ok(not has_table_privilege('authenticated','private.payment_onboarding_intents','select'),'raw provider intents are private');
select ok(not has_table_privilege('authenticated','app.catalog_draft_heads','select'),'draft heads are available only through scope-checked DTOs');
select set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
select throws_like($$select api_v1.list_dashboard_audit_v1('a0000000-0000-0000-0000-000000000001')$$,'%audit_not_authorized%','staff without audit capability is refused');
select throws_like($$select api_v1.authorize_payment_onboarding_v1('a0000000-0000-0000-0000-000000000001','dashboard.tenant-a.example.invalid','en',gen_random_uuid())$$,'%integration_step_up_required%','ordinary staff cannot initiate onboarding');
reset role;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select ok(jsonb_typeof(api_v1.get_schedule_choices_v1('a0000000-0000-0000-0000-000000000001'))='array','authorized named schedule choices are available');
select lives_ok($$select * from api_v1.save_schedule_config_v1('a0000000-0000-0000-0000-000000000001','blackout','{"location_id":"a5000000-0000-0000-0000-000000000001","starts_at":"2026-12-21T14:00:00Z","ends_at":"2026-12-21T15:00:00Z","time_zone":"America/New_York","reason":"Synthetic regression closure"}',null,'a9f10000-0000-4000-8000-000000000002')$$,'blackout save returns without falling into recurring-scope validation');
reset role;
select is((select count(*)::integer from app.blackouts where tenant_id='a0000000-0000-0000-0000-000000000001' and reason='Synthetic regression closure'),1,'blackout save persists exactly one closure');
set local role authenticated;
select throws_like($$select api_v1.list_dashboard_audit_v1('b0000000-0000-0000-0000-000000000001')$$,'%audit_not_authorized%','known second tenant cannot be audited');
select throws_like($$select * from api_v1.create_tenant_v1('Forbidden tenant','forbidden')$$,'%policy_denied%','tenant administrator is not a platform operator');
select set_config('test.schedule_payload','{"scope_id":"a5600000-0000-0000-0000-000000000001","day_of_week":6,"start_minute":600,"end_minute":660}',true);
select set_config('test.schedule_target',(select target_id::text from api_v1.save_schedule_config_v1('a0000000-0000-0000-0000-000000000001','weekly',current_setting('test.schedule_payload')::jsonb,1,'a9f00000-0000-4000-8000-000000000001')),true);
select throws_like($$select * from api_v1.save_schedule_config_v1('a0000000-0000-0000-0000-000000000001','weekly',jsonb_set(current_setting('test.schedule_payload')::jsonb,'{end_minute}','680'),1,'a9f00000-0000-4000-8000-000000000001')$$,'%idempotency_conflict%','changed schedule payload cannot reuse a request');
select throws_like(format($$select * from api_v1.remove_schedule_record_v1('a0000000-0000-0000-0000-000000000001','weekly',%L,1,1,'a9f00000-0000-4000-8000-000000000002')$$,current_setting('test.schedule_target')),'%revision_conflict%','deletion preserves the displayed parent revision');
select lives_ok(format($$select * from api_v1.remove_schedule_record_v1('a0000000-0000-0000-0000-000000000001','weekly',%L,1,2,'a9f00000-0000-4000-8000-000000000003')$$,current_setting('test.schedule_target')),'authorized exact-revision schedule deletion succeeds');
select lives_ok(format($$select * from api_v1.remove_schedule_record_v1('a0000000-0000-0000-0000-000000000001','weekly',%L,1,2,'a9f00000-0000-4000-8000-000000000003')$$,current_setting('test.schedule_target')),'deletion retry returns the first result');
select set_config('test.audit',api_v1.list_dashboard_audit_v1('a0000000-0000-0000-0000-000000000001','schedule')::text,true);
select ok(jsonb_array_length(current_setting('test.audit')::jsonb->'rows')>=2,'audit records actual save and deletion');
select ok(current_setting('test.audit') !~ '(reason|request_hash|redacted_diff|payload|email|intake|token)','audit DTO excludes sensitive source fields');
reset role;
select ok(not exists(select 1 from app.weekly_schedules where id=current_setting('test.schedule_target')::uuid),'successful deletion is persisted');
insert into app.integration_events(tenant_id,actor_auth_user_id,request_id,action,target_id) values('a0000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000002',gen_random_uuid(),'onboarding_authorized',gen_random_uuid());
select throws_ok($$update app.integration_events set action='onboarding_provider_failed'$$,'42501','booking_immutable','integration evidence is append-only');
select * from finish();
rollback;
